#![allow(non_snake_case)]

use super::geometry::{FillRule, Path64, Paths64, Point64};

#[derive(Clone, Copy, Debug)]
struct Rect64 {
    left: i64,
    bottom: i64,
    right: i64,
    top: i64,
}

impl Rect64 {
    fn covers_cell(self, left: i64, bottom: i64, right: i64, top: i64) -> bool {
        left >= self.left && right <= self.right && bottom >= self.bottom && top <= self.top
    }
}

pub fn Area(path: &Path64) -> f64 {
    if path.len() < 3 {
        return 0.0;
    }

    let mut twice_area = 0_i128;
    for index in 0..path.len() {
        let current = path[index];
        let next = path[(index + 1) % path.len()];
        twice_area += i128::from(current.x) * i128::from(next.y)
            - i128::from(current.y) * i128::from(next.x);
    }

    twice_area as f64 / 2.0
}

pub fn TranslatePaths(paths: &Paths64, delta_x: i64, delta_y: i64) -> Paths64 {
    paths
        .iter()
        .map(|path| {
            path.iter()
                .map(|point| Point64::new(point.x + delta_x, point.y + delta_y))
                .collect()
        })
        .collect()
}

pub fn Union(subjects: Paths64, _fill_rule: FillRule) -> Paths64 {
    let mut rectangles = Vec::with_capacity(subjects.len());
    for path in &subjects {
        match extract_rectangle(path) {
            Some(rectangle) => rectangles.push(rectangle),
            None => return subjects,
        }
    }

    union_rectangles(&rectangles)
}

fn extract_rectangle(path: &Path64) -> Option<Rect64> {
    if path.len() != 4 {
        return None;
    }

    for index in 0..path.len() {
        let current = path[index];
        let next = path[(index + 1) % path.len()];
        let horizontal = current.y == next.y && current.x != next.x;
        let vertical = current.x == next.x && current.y != next.y;
        if !horizontal && !vertical {
            return None;
        }
    }

    let mut xs = [path[0].x, path[1].x, path[2].x, path[3].x];
    let mut ys = [path[0].y, path[1].y, path[2].y, path[3].y];
    xs.sort_unstable();
    ys.sort_unstable();

    if xs[0] != xs[1] || xs[2] != xs[3] || ys[0] != ys[1] || ys[2] != ys[3] {
        return None;
    }

    if xs[0] == xs[2] || ys[0] == ys[2] {
        return None;
    }

    Some(Rect64 {
        left: xs[0],
        bottom: ys[0],
        right: xs[2],
        top: ys[2],
    })
}

fn union_rectangles(rectangles: &[Rect64]) -> Paths64 {
    if rectangles.is_empty() {
        return Vec::new();
    }

    let mut xs = Vec::with_capacity(rectangles.len() * 2);
    let mut ys = Vec::with_capacity(rectangles.len() * 2);
    for rectangle in rectangles {
        xs.push(rectangle.left);
        xs.push(rectangle.right);
        ys.push(rectangle.bottom);
        ys.push(rectangle.top);
    }
    xs.sort_unstable();
    ys.sort_unstable();
    xs.dedup();
    ys.dedup();

    let mut result = Vec::new();
    for x_index in 0..xs.len().saturating_sub(1) {
        let left = xs[x_index];
        let right = xs[x_index + 1];
        if left == right {
            continue;
        }

        for y_index in 0..ys.len().saturating_sub(1) {
            let bottom = ys[y_index];
            let top = ys[y_index + 1];
            if bottom == top {
                continue;
            }

            if rectangles
                .iter()
                .any(|rectangle| rectangle.covers_cell(left, bottom, right, top))
            {
                result.push(vec![
                    Point64::new(left, bottom),
                    Point64::new(right, bottom),
                    Point64::new(right, top),
                    Point64::new(left, top),
                ]);
            }
        }
    }

    result
}
